"""Constructive Collapse Principle: k genuine observers -> 2 genuine observers."""
from __future__ import annotations
from typing import FrozenSet, List, Tuple

Set = FrozenSet[int]
Topology = FrozenSet[Set]


def consensus(observers: List[Topology]) -> Topology:
    result = set(observers[0])
    for t in observers[1:]:
        result &= set(t)
    return frozenset(result)


def strictly_finer(observer: Topology, real: Topology) -> bool:
    return set(real) < set(observer)


def collapse_to_two(observers: List[Topology], real: Topology) -> Tuple[Topology, Topology]:
    """Peel one observer; pool the rest. If the pool is strictly finer, done;
    otherwise recurse on the strictly smaller family (never bottoms out at one)."""
    fam = list(observers)
    while True:
        head, rest = fam[0], fam[1:]
        pooled = consensus(rest)
        if strictly_finer(pooled, real):
            return head, pooled
        fam = rest  # pooled == real: descend


if __name__ == "__main__":
    X = frozenset({0, 1})
    s0 = frozenset({frozenset(), frozenset({0}), X})
    s1 = frozenset({frozenset(), frozenset({1}), X})
    disc = frozenset({frozenset(), frozenset({0}), frozenset({1}), X})  # redundant
    real = consensus([s0, s1, disc])
    b, c = collapse_to_two([s0, s1, disc], real)
    print("3 observers collapse to 2:", sorted(map(sorted, b)), sorted(map(sorted, c)))
    print("consensus preserved:", consensus([b, c]) == real)

