from __future__ import annotations


def in_left(a: float, x: float, t: float) -> bool:   # (a, x]
    return a < t <= x


def in_right(x: float, b: float, t: float) -> bool:  # [x, b)
    return x <= t < b


def in_open(a: float, b: float, t: float) -> bool:   # (a, b)
    return a < t < b


def squeeze_holds(a: float, x: float, b: float, n: int = 20001) -> bool:
    lo, hi = a - 1.0, b + 1.0
    for k in range(n):
        t = lo + (hi - lo) * k / (n - 1)
        if (in_left(a, x, t) or in_right(x, b, t)) != in_open(a, b, t):
            return False
    return True


if __name__ == "__main__":
